bool Codec<SurveyResponseBody>::encode(const SurveyResponseBody& v, Encoder& e) {
  switch (v.t_) {
    case SurveyMessageResponseType::SURVEY_TOPOLOGY_RESPONSE_V2:
      if (const auto* p = std::get_if<0>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "SurveyResponseBody: payload does not match discriminant");
    default: return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "SurveyResponseBody: unknown discriminant");
  }
}

bool Codec<SurveyResponseBody>::decode(SurveyResponseBody& v, Decoder& d) {
  Decoder::DepthGuard g(d);
  if (!g) return false;
  std::int32_t tag;
  if (!d.i32(tag)) return false;
  switch (tag) {
    case 2:
      v.t_ = static_cast<SurveyMessageResponseType>(tag);
      v.v_.template emplace<0>();
      return d.field("topologyResponseBodyV2", std::get<0>(v.v_));
    default: return d.fail(stellar::v1::ErrorCode::kDecodeFailed, "SurveyResponseBody: unknown discriminant");
  }
}

bool Codec<SurveyResponseBody>::gen(SurveyResponseBody& v, XdrRng& r, std::uint32_t depth) {
  std::size_t i = depth >= 4 ? 0 : r.index(1);
  switch (i) {
    case 0: {
      v.t_ = SurveyMessageResponseType::SURVEY_TOPOLOGY_RESPONSE_V2;
      auto& p = v.v_.template emplace<0>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
  }
  return false;
}

