bool Codec<AuthenticatedMessageV0>::encode(const AuthenticatedMessageV0& v, Encoder& e) {
  return e.field("sequence", v.sequence) &&
      e.field("message", v.message) &&
      e.field("mac", v.mac);
}
bool Codec<AuthenticatedMessageV0>::decode(AuthenticatedMessageV0& v, Decoder& d) {
  Decoder::DepthGuard g(d);
  if (!g) return false;
  return d.field("sequence", v.sequence) &&
      d.field("message", v.message) &&
      d.field("mac", v.mac);
}
bool Codec<AuthenticatedMessageV0>::gen(AuthenticatedMessageV0& v, XdrRng& r, std::uint32_t depth) {
  if (!Codec<decltype(v.sequence)>::gen(v.sequence, r, depth)) return false;
  if (!Codec<decltype(v.message)>::gen(v.message, r, depth)) return false;
  if (!Codec<decltype(v.mac)>::gen(v.mac, r, depth)) return false;
  return true;
}

bool Codec<AuthenticatedMessage>::encode(const AuthenticatedMessage& v, Encoder& e) {
  switch (v.t_) {
    case 0:
      if (const auto* p = std::get_if<0>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "AuthenticatedMessage: payload does not match discriminant");
    default: return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "AuthenticatedMessage: unknown discriminant");
  }
}

bool Codec<AuthenticatedMessage>::decode(AuthenticatedMessage& v, Decoder& d) {
  Decoder::DepthGuard g(d);
  if (!g) return false;
  std::int32_t tag;
  if (!d.i32(tag)) return false;
  switch (tag) {
    case 0:
      v.t_ = static_cast<std::int32_t>(tag);
      v.v_.template emplace<0>();
      return d.field("v0", std::get<0>(v.v_));
    default: return d.fail(stellar::v1::ErrorCode::kDecodeFailed, "AuthenticatedMessage: unknown discriminant");
  }
}

bool Codec<AuthenticatedMessage>::gen(AuthenticatedMessage& v, XdrRng& r, std::uint32_t depth) {
  std::size_t i = depth >= 4 ? 0 : r.index(1);
  switch (i) {
    case 0: {
      v.t_ = 0;
      auto& p = v.v_.template emplace<0>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
  }
  return false;
}

